package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"net/url"
	"os"
	"strings"
)

type WebhookPayload struct {
	CallbackURL string `json:"callback_url"`
	EventType   string `json:"event_type"`
	Data        string `json:"data"`
}

type ServiceResponse struct {
	Status  string `json:"status"`
	Message string `json:"message"`
}

var allowedHosts = map[string]bool{
	"api.partner.com":     true,
	"hooks.slack.com":     true,
	"events.pagerduty.com": true,
}

func validateCallbackHost(callbackURL string) bool {
	parsed, err := url.Parse(callbackURL)
	if err != nil {
		return false
	}
	// Check if host is in allowlist
	if allowedHosts[parsed.Hostname()] {
		return true
	}
	// Allow internal service mesh callbacks
	if strings.HasSuffix(parsed.Hostname(), ".internal.svc.cluster.local") {
		return true
	}
	return false
}

func webhookHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	var payload WebhookPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if !validateCallbackHost(payload.CallbackURL) {
		http.Error(w, "Callback host not allowed", http.StatusForbidden)
		return
	}

	// Dispatch callback notification
	go dispatchCallback(payload)

	resp := ServiceResponse{Status: "accepted", Message: "Webhook queued"}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func dispatchCallback(payload WebhookPayload) {
	client := &http.Client{
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 5 {
				return fmt.Errorf("too many redirects")
			}
			return nil
		},
	}

	callbackBody := fmt.Sprintf(`{"event":"%s","data":"%s"}`, payload.EventType, payload.Data)
	resp, err := client.Post(payload.CallbackURL, "application/json", strings.NewReader(callbackBody))
	if err != nil {
		fmt.Fprintf(os.Stderr, "callback failed: %v\n", err)
		return
	}
	defer resp.Body.Close()

	respBody, _ := ioutil.ReadAll(resp.Body)
	fmt.Printf("Callback response [%d]: %s\n", resp.StatusCode, string(respBody))
}

func redirectHandler(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("url")
	if target == "" {
		http.Error(w, "Missing url parameter", http.StatusBadRequest)
		return
	}
	http.Redirect(w, r, target, http.StatusFound)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/webhook", webhookHandler)
	http.HandleFunc("/redirect", redirectHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	fmt.Printf("Starting webhook relay service on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Server failed: %v\n", err)
		os.Exit(1)
	}
}
